create extension if not exists pgcrypto;
create table if not exists public.menu_categories (id uuid primary key default gen_random_uuid(), name text not null, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.menu_products (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.menu_categories(id) on delete restrict, name text not null, description text, price numeric(12,2) not null check (price >= 0), image_url text, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.customers (id uuid primary key default gen_random_uuid(), telegram_user_id bigint not null unique, username text, first_name text, last_name text, phone text, default_address text, default_latitude double precision, default_longitude double precision, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.orders (id bigint generated by default as identity primary key, customer_id uuid not null references public.customers(id) on delete restrict, status text not null default 'pending' check (status in ('pending','confirmed','preparing','ready','out_for_delivery','delivered','cancelled')), delivery_type text not null check (delivery_type in ('pickup','delivery')), delivery_address text, latitude double precision, longitude double precision, payment_method text not null default 'cash', payment_status text not null default 'pending' check (payment_status in ('pending','paid','failed','refunded')), subtotal numeric(12,2) not null check (subtotal >= 0), delivery_fee numeric(12,2) not null default 0 check (delivery_fee >= 0), total numeric(12,2) not null check (total >= 0), currency text not null default 'SYP', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.order_items (id bigint generated by default as identity primary key, order_id bigint not null references public.orders(id) on delete cascade, product_id uuid references public.menu_products(id) on delete set null, product_name text not null, unit_price numeric(12,2) not null, quantity integer not null check (quantity > 0), line_total numeric(12,2) not null);
create index if not exists idx_menu_products_category on public.menu_products(category_id, is_active, sort_order);
create index if not exists idx_orders_customer on public.orders(customer_id, created_at desc);
create index if not exists idx_orders_status on public.orders(status, created_at desc);
alter table public.menu_categories enable row level security;
alter table public.menu_products enable row level security;
alter table public.customers enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
